import {mapGetters} from "vuex";

export default {

  props: {
    dialogType: {
      type: String,
      default: 'add'
    },
    cameraData: {
      type: Object,
      default: () => ({})
    },
    nvrInfo:{
      type: Object,
      default: () => ({})
    }
  },
  computed: {
    ...mapGetters(["permission", "userInfo", 'userDetail'])
  },
  watch: {
    dialogType: {
      handler(newValue) {
        this.type = newValue
      }
    },
    cameraData: {
      handler(newValue) {
        this.form = newValue
      },
      deep: true,
      immediate: true
    }
  },
  data() {
    return {
      form: {},
      userInfo:this.$store.state.user.userDetail,
      type: "",
      rules: {
        name: [
          {required: true, message: '请输入名称', trigger: 'blur'}
        ],
        ip: [
          {required: true, message: '请输入IP地址', trigger: 'blur'},
          {
            required: true,
            pattern: /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
            message: 'IP地址格式有误',
            trigger: 'blur'
          }
        ],
        port: [
          {required: true, message: '请输入端口', trigger: 'blur'}
        ],
        channel: [
          {required: true, message: '请输入通道编号', trigger: 'blur'}
        ],
      }
    };
  },
  methods: {
    /**
     * 提交表单
     */
    submitForm() {
      this.$refs.form.validate(valid => {
        if (valid) {
          this.form.nvrId=this.nvrInfo.id;
          this.form.companyId=this.userInfo.ownerUnit
          this.form.roomId=this.nvrInfo.roomId
          this.form.companyName=this.userInfo.ownerUnitName
          if (this.dialogType === 'add') {
            this.$emit('submit', this.form, this.dialogType)
          }
          if (this.dialogType === 'edit') {
            this.$emit('submit', this.form, this.dialogType)
          }
        } else {
          return false;
        }
      });
    },
    /**
     * 关闭弹层
     */
    cancelForm() {
      this.$emit('addAndEditCloseDialog')
    },
    /**
     * 清空表单校验
     */
    clearValidate() {
      this.$refs.form.clearValidate()
    },
  }
}
